#!/usr/bin/env python3
"""
Build and validate Psyche's truthful CUDA driver/runtime/cuBLAS stub libraries.

The stubs are intentionally not a CUDA implementation. They exist so dynamic
CUDA discovery can find libraries that report no CUDA devices instead of
spoofing an Apple GPU. The cuBLAS shim is also explicit-opt-in and CPU-backed.

Run:

    python3 scripts/check-cuda-driver-stubs.py
"""

from __future__ import annotations

import ctypes
import math
import os
import platform
import subprocess
import sys
import threading
from pathlib import Path


