def dylib_suffix() -> str:
    if sys.platform == "darwin":
        return ".dylib"
    if os.name == "nt":
        return ".dll"
    return ".so"


def shared_library_flags(
    output: Path,
    source: Path,
    include_dir: Path,
    extra_sources: list[Path] | None = None,
    objc_frameworks: list[str] | None = None,
    weak_objc_frameworks: list[str] | None = None,
) -> list[str]:
    compiler = os.environ.get("CC", "clang" if sys.platform == "darwin" else "cc")
    sources = [source, *(extra_sources or [])]
    common = [
        compiler,
        "-std=c11",
        "-Wall",
        "-Wextra",
        "-Werror",
        "-fvisibility=hidden",
        "-I",
        str(include_dir),
        *(str(item) for item in sources),
        "-o",
        str(output),
    ]
    if sys.platform == "darwin":
        framework_flags = [
            flag
            for framework in (objc_frameworks or [])
            for flag in ("-framework", framework)
        ]
        weak_framework_flags = [
            flag
            for framework in (weak_objc_frameworks or [])
            for flag in ("-weak_framework", framework)
        ]
        objc_flags = ["-fobjc-arc"] if objc_frameworks else []
        return common[:1] + ["-dynamiclib", *objc_flags] + common[1:] + framework_flags + weak_framework_flags
    return common[:1] + ["-shared", "-fPIC"] + common[1:]


def build_stub(source_name: str, output_name: str) -> Path:
    repo_root = Path(__file__).resolve().parents[1]
    source_dir = repo_root / "tools/cuda-compat-shim"
    build_dir = repo_root / "target/cuda-compat-shim"
    build_dir.mkdir(parents=True, exist_ok=True)
    output = build_dir / output_name
    extra_sources = []
    objc_frameworks = []
    weak_objc_frameworks = []
    if source_name in ("libcuda_stub.c", "libcublas_stub.c", "libcusparse_stub.c", "libcudnn_stub.c") and sys.platform == "darwin":
        extra_sources.append(source_dir / "libcuda_metal_backend.m")
        objc_frameworks.extend(["Foundation", "Metal"])
    if source_name == "libcudnn_stub.c" and sys.platform == "darwin":
        weak_objc_frameworks.append("MetalPerformanceShadersGraph")
    if source_name in ("libcublas_stub.c", "libcublasLt_stub.c", "libcusolver_stub.c") and sys.platform == "darwin":
        objc_frameworks.append("Accelerate")
    cmd = shared_library_flags(
        output,
        source_dir / source_name,
        source_dir,
        extra_sources=extra_sources,
        objc_frameworks=objc_frameworks,
        weak_objc_frameworks=weak_objc_frameworks,
    )
    subprocess.run(cmd, cwd=repo_root, check=True)
    return output


def executable_flags(output: Path, source: Path, include_dir: Path) -> list[str]:
    compiler = os.environ.get("CC", "clang" if sys.platform == "darwin" else "cc")
    cmd = [
        compiler,
        "-std=c11",
        "-Wall",
        "-Wextra",
        "-Werror",
        "-I",
        str(include_dir),
        str(source),
        "-o",
        str(output),
    ]
    if sys.platform != "darwin":
        cmd.append("-ldl")
    return cmd


def check_fixed_prototype_abi(libcuda_path: Path, libcudart_path: Path) -> None:
    repo_root = Path(__file__).resolve().parents[1]
    source_dir = repo_root / "tools/cuda-compat-shim"
    build_dir = repo_root / "target/cuda-compat-shim"
    source = build_dir / "check_fixed_cuda_abi.c"
    executable = build_dir / "check_fixed_cuda_abi"
    source.write_text(
        r'''
#include "cuda_compat_stub.h"

#include <dlfcn.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

_Static_assert(sizeof(cuComplex) == sizeof(float) * 2, "cuComplex must stay two floats");
_Static_assert(_Alignof(cuComplex) == _Alignof(float), "cuComplex alignment must match float");
_Static_assert(offsetof(cuComplex, x) == 0, "cuComplex.x offset");
_Static_assert(offsetof(cuComplex, y) == sizeof(float), "cuComplex.y offset");
_Static_assert(sizeof(cuDoubleComplex) == sizeof(double) * 2, "cuDoubleComplex must stay two doubles");
_Static_assert(_Alignof(cuDoubleComplex) == _Alignof(double), "cuDoubleComplex alignment must match double");
_Static_assert(offsetof(cuDoubleComplex, x) == 0, "cuDoubleComplex.x offset");
_Static_assert(offsetof(cuDoubleComplex, y) == sizeof(double), "cuDoubleComplex.y offset");
_Static_assert(sizeof(cublasLtMatrixLayoutOpaque_t) == sizeof(uint64_t) * 8, "cuBLASLt layout opaque size");
_Static_assert(sizeof(cublasLtMatmulAlgo_t) == sizeof(uint64_t) * 8, "cuBLASLt algo opaque size");
_Static_assert(sizeof(cublasLtMatmulDescOpaque_t) == sizeof(uint64_t) * 32, "cuBLASLt matmul desc opaque size");
_Static_assert(sizeof(cublasLtMatrixTransformDescOpaque_t) == sizeof(uint64_t) * 8, "cuBLASLt transform desc opaque size");
_Static_assert(sizeof(cublasLtMatmulPreferenceOpaque_t) == sizeof(uint64_t) * 8, "cuBLASLt preference opaque size");
_Static_assert(offsetof(cublasLtMatmulHeuristicResult_t, workspaceSize) == sizeof(cublasLtMatmulAlgo_t), "cuBLASLt heuristic workspace offset");
_Static_assert(sizeof(((cublasLtMatmulHeuristicResult_t *)0)->reserved) == sizeof(int) * 4, "cuBLASLt heuristic reserved shape");

typedef CUresult (*cuInit_fn)(unsigned int);
typedef CUresult (*cuMemAllocAsync_fn)(CUdeviceptr *, size_t, CUstream);
typedef CUresult (*cuMemAllocFromPoolAsync_fn)(CUdeviceptr *, size_t, CUmemoryPool, CUstream);
typedef CUresult (*cuMemAllocManaged_fn)(CUdeviceptr *, size_t, unsigned int);
typedef CUresult (*cuMemAdvise_fn)(CUdeviceptr, size_t, CUmem_advise, CUdevice);
typedef CUresult (*cuMemPrefetchAsync_fn)(CUdeviceptr, size_t, CUdevice, CUstream);
typedef CUresult (*cuMemFree_fn)(CUdeviceptr);
typedef CUresult (*cuMemFreeAsync_fn)(CUdeviceptr, CUstream);
typedef CUresult (*cuMemPoolCreate_fn)(CUmemoryPool *, const CUmemPoolProps *);
typedef CUresult (*cuMemPoolDestroy_fn)(CUmemoryPool);
typedef CUresult (*cuMemPoolGetAttribute_fn)(CUmemoryPool, CUmemPool_attribute, void *);
typedef cudaError_t (*cudaMallocManaged_fn)(void **, size_t, unsigned int);
typedef cudaError_t (*cudaMallocAsync_fn)(void **, size_t, cudaStream_t);
typedef cudaError_t (*cudaMallocFromPoolAsync_fn)(void **, size_t, cudaMemPool_t, cudaStream_t);
typedef cudaError_t (*cudaMemAdvise_fn)(const void *, size_t, cudaMemoryAdvise, int);
typedef cudaError_t (*cudaMemPrefetchAsync_fn)(const void *, size_t, int, cudaStream_t);
typedef cudaError_t (*cudaFree_fn)(void *);
typedef cudaError_t (*cudaFreeAsync_fn)(void *, cudaStream_t);
typedef cudaError_t (*cudaMemPoolCreate_fn)(cudaMemPool_t *, const cudaMemPoolProps *);
typedef cudaError_t (*cudaMemPoolDestroy_fn)(cudaMemPool_t);
typedef cudaError_t (*cudaMemPoolGetAttribute_fn)(cudaMemPool_t, cudaMemPoolAttr, void *);

static void *require_symbol(void *library, const char *name) {
  void *symbol = dlsym(library, name);
  if (symbol == 0) {
    fprintf(stderr, "missing symbol %s\n", name);
    exit(2);
  }
  return symbol;
}

int main(int argc, char **argv) {
  void *libcuda = 0;
  void *libcudart = 0;
  cuInit_fn p_cuInit = 0;
  cuMemAllocAsync_fn p_cuMemAllocAsync = 0;
  cuMemAllocFromPoolAsync_fn p_cuMemAllocFromPoolAsync = 0;
  cuMemAllocManaged_fn p_cuMemAllocManaged = 0;
  cuMemAdvise_fn p_cuMemAdvise = 0;
  cuMemPrefetchAsync_fn p_cuMemPrefetchAsync = 0;
  cuMemFree_fn p_cuMemFree = 0;
  cuMemFreeAsync_fn p_cuMemFreeAsync = 0;
  cuMemPoolCreate_fn p_cuMemPoolCreate = 0;
  cuMemPoolDestroy_fn p_cuMemPoolDestroy = 0;
  cuMemPoolGetAttribute_fn p_cuMemPoolGetAttribute = 0;
  cudaMallocManaged_fn p_cudaMallocManaged = 0;
  cudaMallocAsync_fn p_cudaMallocAsync = 0;
  cudaMallocFromPoolAsync_fn p_cudaMallocFromPoolAsync = 0;
  cudaMemAdvise_fn p_cudaMemAdvise = 0;
  cudaMemPrefetchAsync_fn p_cudaMemPrefetchAsync = 0;
  cudaFree_fn p_cudaFree = 0;
  cudaFreeAsync_fn p_cudaFreeAsync = 0;
  cudaMemPoolCreate_fn p_cudaMemPoolCreate = 0;
  cudaMemPoolDestroy_fn p_cudaMemPoolDestroy = 0;
  cudaMemPoolGetAttribute_fn p_cudaMemPoolGetAttribute = 0;
  CUdeviceptr driver_ptr = 0;
  CUdeviceptr driver_async_ptr = 0;
  CUdeviceptr driver_pool_ptr = 0;
  CUmemoryPool driver_pool = 0;
  CUmemPoolProps driver_pool_props;
  cuuint64_t driver_pool_used = 0;
  void *runtime_ptr = 0;
  void *runtime_async_ptr = 0;
  void *runtime_pool_ptr = 0;
  cudaMemPool_t runtime_pool = 0;
  cudaMemPoolProps runtime_pool_props;
  cuuint64_t runtime_pool_used = 0;

  if (argc != 3) {
    fprintf(stderr, "usage: %s libcuda libcudart\n", argv[0]);
    return 2;
  }
  libcuda = dlopen(argv[1], RTLD_NOW);
  if (libcuda == 0) {
    fprintf(stderr, "dlopen libcuda failed: %s\n", dlerror());
    return 2;
  }
  libcudart = dlopen(argv[2], RTLD_NOW);
  if (libcudart == 0) {
    fprintf(stderr, "dlopen libcudart failed: %s\n", dlerror());
    return 2;
  }

  p_cuInit = (cuInit_fn)require_symbol(libcuda, "cuInit");
  p_cuMemAllocAsync = (cuMemAllocAsync_fn)require_symbol(libcuda, "cuMemAllocAsync");
  p_cuMemAllocFromPoolAsync = (cuMemAllocFromPoolAsync_fn)require_symbol(libcuda, "cuMemAllocFromPoolAsync");
  p_cuMemAllocManaged = (cuMemAllocManaged_fn)require_symbol(libcuda, "cuMemAllocManaged");
  p_cuMemAdvise = (cuMemAdvise_fn)require_symbol(libcuda, "cuMemAdvise");
  p_cuMemPrefetchAsync = (cuMemPrefetchAsync_fn)require_symbol(libcuda, "cuMemPrefetchAsync");
  p_cuMemFree = (cuMemFree_fn)require_symbol(libcuda, "cuMemFree");
  p_cuMemFreeAsync = (cuMemFreeAsync_fn)require_symbol(libcuda, "cuMemFreeAsync");
  p_cuMemPoolCreate = (cuMemPoolCreate_fn)require_symbol(libcuda, "cuMemPoolCreate");
  p_cuMemPoolDestroy = (cuMemPoolDestroy_fn)require_symbol(libcuda, "cuMemPoolDestroy");
  p_cuMemPoolGetAttribute = (cuMemPoolGetAttribute_fn)require_symbol(libcuda, "cuMemPoolGetAttribute");
  p_cudaMallocManaged = (cudaMallocManaged_fn)require_symbol(libcudart, "cudaMallocManaged");
  p_cudaMallocAsync = (cudaMallocAsync_fn)require_symbol(libcudart, "cudaMallocAsync");
  p_cudaMallocFromPoolAsync = (cudaMallocFromPoolAsync_fn)require_symbol(libcudart, "cudaMallocFromPoolAsync");
  p_cudaMemAdvise = (cudaMemAdvise_fn)require_symbol(libcudart, "cudaMemAdvise");
  p_cudaMemPrefetchAsync = (cudaMemPrefetchAsync_fn)require_symbol(libcudart, "cudaMemPrefetchAsync");
  p_cudaFree = (cudaFree_fn)require_symbol(libcudart, "cudaFree");
  p_cudaFreeAsync = (cudaFreeAsync_fn)require_symbol(libcudart, "cudaFreeAsync");
  p_cudaMemPoolCreate = (cudaMemPoolCreate_fn)require_symbol(libcudart, "cudaMemPoolCreate");
  p_cudaMemPoolDestroy = (cudaMemPoolDestroy_fn)require_symbol(libcudart, "cudaMemPoolDestroy");
  p_cudaMemPoolGetAttribute = (cudaMemPoolGetAttribute_fn)require_symbol(libcudart, "cudaMemPoolGetAttribute");

  if (p_cuInit(0) != CUDA_ERROR_NO_DEVICE) {
    fprintf(stderr, "cuInit should initialize truthfully with no-device\n");
    return 1;
  }
  if (p_cuMemAllocManaged(&driver_ptr, 32, CU_MEM_ATTACH_GLOBAL) != CUDA_SUCCESS || driver_ptr == 0) {
    fprintf(stderr, "fixed-prototype cuMemAllocManaged failed\n");
    return 1;
  }
  if (((uintptr_t)driver_ptr % 256U) != 0U) {
    fprintf(stderr, "driver managed allocation is not 256-byte aligned\n");
    return 1;
  }
  if (p_cuMemAdvise(driver_ptr, 32, CU_MEM_ADVISE_SET_READ_MOSTLY, CU_DEVICE_CPU) != CUDA_SUCCESS) {
    fprintf(stderr, "fixed-prototype cuMemAdvise CPU failed\n");
    return 1;
  }
  if (p_cuMemPrefetchAsync(driver_ptr, 32, CU_DEVICE_CPU, 0) != CUDA_SUCCESS) {
    fprintf(stderr, "fixed-prototype cuMemPrefetchAsync CPU failed\n");
    return 1;
  }
  if (p_cuMemPrefetchAsync(driver_ptr, 32, 0, 0) != CUDA_ERROR_INVALID_DEVICE) {
    fprintf(stderr, "fixed-prototype cuMemPrefetchAsync GPU should fail invalid-device\n");
    return 1;
  }
  if (p_cuMemFree(driver_ptr) != CUDA_SUCCESS) {
    fprintf(stderr, "driver managed allocation free failed\n");
    return 1;
  }
  if (p_cuMemAllocAsync(&driver_async_ptr, 64, 0) != CUDA_SUCCESS || driver_async_ptr == 0) {
    fprintf(stderr, "fixed-prototype cuMemAllocAsync failed\n");
    return 1;
  }
  if (((uintptr_t)driver_async_ptr % 256U) != 0U) {
    fprintf(stderr, "driver async allocation is not 256-byte aligned\n");
    return 1;
  }
  if (p_cuMemFreeAsync(driver_async_ptr, 0) != CUDA_SUCCESS) {
    fprintf(stderr, "fixed-prototype cuMemFreeAsync failed\n");
    return 1;
  }
  memset(&driver_pool_props, 0, sizeof(driver_pool_props));
  driver_pool_props.allocType = CU_MEM_ALLOCATION_TYPE_PINNED;
  driver_pool_props.handleTypes = CU_MEM_HANDLE_TYPE_NONE;
  driver_pool_props.location.id = CU_DEVICE_CPU;
  driver_pool_props.location.type = CU_MEM_LOCATION_TYPE_HOST;
  if (p_cuMemPoolCreate(&driver_pool, &driver_pool_props) != CUDA_SUCCESS || driver_pool == 0) {
    fprintf(stderr, "fixed-prototype cuMemPoolCreate failed\n");
    return 1;
  }
  if (p_cuMemAllocFromPoolAsync(&driver_pool_ptr, 48, driver_pool, 0) != CUDA_SUCCESS || driver_pool_ptr == 0) {
    fprintf(stderr, "fixed-prototype cuMemAllocFromPoolAsync failed\n");
    return 1;
  }
  if (p_cuMemPoolGetAttribute(driver_pool, CU_MEMPOOL_ATTR_USED_MEM_CURRENT, &driver_pool_used) != CUDA_SUCCESS || driver_pool_used != 48) {
    fprintf(stderr, "fixed-prototype cuMemPoolGetAttribute failed\n");
    return 1;
  }
  if (p_cuMemFreeAsync(driver_pool_ptr, 0) != CUDA_SUCCESS) {
    fprintf(stderr, "driver pool allocation async free failed\n");
    return 1;
  }
  if (p_cuMemPoolDestroy(driver_pool) != CUDA_SUCCESS) {
    fprintf(stderr, "fixed-prototype cuMemPoolDestroy failed\n");
    return 1;
  }

  if (p_cudaMallocManaged(&runtime_ptr, 32, cudaMemAttachGlobal) != cudaSuccess || runtime_ptr == 0) {
    fprintf(stderr, "fixed-prototype cudaMallocManaged failed\n");
    return 1;
  }
  if (((uintptr_t)runtime_ptr % 256U) != 0U) {
    fprintf(stderr, "runtime managed allocation is not 256-byte aligned\n");
    return 1;
  }
  if (p_cudaMemAdvise(runtime_ptr, 32, cudaMemAdviceSetReadMostly, cudaCpuDeviceId) != cudaSuccess) {
    fprintf(stderr, "fixed-prototype cudaMemAdvise CPU failed\n");
    return 1;
  }
  if (p_cudaMemPrefetchAsync(runtime_ptr, 32, cudaCpuDeviceId, 0) != cudaSuccess) {
    fprintf(stderr, "fixed-prototype cudaMemPrefetchAsync CPU failed\n");
    return 1;
  }
  if (p_cudaMemPrefetchAsync(runtime_ptr, 32, 0, 0) != cudaErrorInvalidDevice) {
    fprintf(stderr, "fixed-prototype cudaMemPrefetchAsync GPU should fail invalid-device\n");
    return 1;
  }
  if (p_cudaFree(runtime_ptr) != cudaSuccess) {
    fprintf(stderr, "runtime managed allocation free failed\n");
    return 1;
  }
  if (p_cudaMallocAsync(&runtime_async_ptr, 64, 0) != cudaSuccess || runtime_async_ptr == 0) {
    fprintf(stderr, "fixed-prototype cudaMallocAsync failed\n");
    return 1;
  }
  if (((uintptr_t)runtime_async_ptr % 256U) != 0U) {
    fprintf(stderr, "runtime async allocation is not 256-byte aligned\n");
    return 1;
  }
  if (p_cudaFreeAsync(runtime_async_ptr, 0) != cudaSuccess) {
    fprintf(stderr, "fixed-prototype cudaFreeAsync failed\n");
    return 1;
  }
  memset(&runtime_pool_props, 0, sizeof(runtime_pool_props));
  runtime_pool_props.allocType = cudaMemAllocationTypePinned;
  runtime_pool_props.handleTypes = cudaMemHandleTypeNone;
  runtime_pool_props.location.id = cudaCpuDeviceId;
  runtime_pool_props.location.type = cudaMemLocationTypeHost;
  if (p_cudaMemPoolCreate(&runtime_pool, &runtime_pool_props) != cudaSuccess || runtime_pool == 0) {
    fprintf(stderr, "fixed-prototype cudaMemPoolCreate failed\n");
    return 1;
  }
  if (p_cudaMallocFromPoolAsync(&runtime_pool_ptr, 48, runtime_pool, 0) != cudaSuccess || runtime_pool_ptr == 0) {
    fprintf(stderr, "fixed-prototype cudaMallocFromPoolAsync failed\n");
    return 1;
  }
  if (p_cudaMemPoolGetAttribute(runtime_pool, cudaMemPoolAttrUsedMemCurrent, &runtime_pool_used) != cudaSuccess || runtime_pool_used != 48) {
    fprintf(stderr, "fixed-prototype cudaMemPoolGetAttribute failed\n");
    return 1;
  }
  if (p_cudaFreeAsync(runtime_pool_ptr, 0) != cudaSuccess) {
    fprintf(stderr, "runtime pool allocation async free failed\n");
    return 1;
  }
  if (p_cudaMemPoolDestroy(runtime_pool) != cudaSuccess) {
    fprintf(stderr, "fixed-prototype cudaMemPoolDestroy failed\n");
    return 1;
  }

  dlclose(libcudart);
  dlclose(libcuda);
  return 0;
}
''',
        encoding="utf-8",
    )
    subprocess.run(executable_flags(executable, source, source_dir), cwd=repo_root, check=True)
    env = os.environ.copy()
    env[SIMULATED_MEMORY_ENV] = "1"
    subprocess.run([str(executable), str(libcuda_path), str(libcudart_path)], cwd=repo_root, env=env, check=True)


def exported_symbols(library_path: Path) -> set[str]:
    proc = subprocess.run(
        ["nm", "-gU", str(library_path)],
        text=True,
        capture_output=True,
        check=True,
    )
    symbols: set[str] = set()
    for line in proc.stdout.splitlines():
        parts = line.split()
        if len(parts) < 3 or parts[-2] != "T":
            continue
        symbol = parts[-1]
        if symbol.startswith("_"):
            symbol = symbol[1:]
        symbols.add(symbol)
    return symbols


def check_exported_symbols(library_path: Path, expected: set[str]) -> None:
    got = exported_symbols(library_path)
    if got != expected:
        missing = sorted(expected - got)
        extra = sorted(got - expected)
        raise AssertionError(
            f"unexpected exported symbols for {library_path}: "
            f"missing={missing} extra={extra}"
        )


def check_no_exported_symbol_prefix(library_path: Path, prefix: str) -> None:
    leaked = sorted(symbol for symbol in exported_symbols(library_path) if symbol.startswith(prefix))
    if leaked:
        raise AssertionError(f"{library_path} should not export private {prefix!r} symbols: {leaked}")


def check_linked_frameworks(library_path: Path, expected_frameworks: set[str]) -> None:
    proc = subprocess.run(
        ["otool", "-L", str(library_path)],
        text=True,
        capture_output=True,
        check=True,
    )
    missing = sorted(
        framework
        for framework in expected_frameworks
        if f"/{framework}.framework/" not in proc.stdout
    )
    if missing:
        raise AssertionError(f"{library_path} is missing expected framework links: {missing}")


def check_undefined_symbols(library_path: Path, expected: set[str]) -> None:
    proc = subprocess.run(
        ["nm", "-u", str(library_path)],
        text=True,
        capture_output=True,
        check=True,
    )
    got = set()
    for line in proc.stdout.splitlines():
        symbol = line.strip()
        if symbol.startswith("_"):
            symbol = symbol[1:]
        if symbol:
            got.add(symbol)
    missing = sorted(expected - got)
    if missing:
        raise AssertionError(f"{library_path} is missing expected undefined symbols: {missing}")


def check_driver_proc_contract() -> None:
    proc_contract = EXPECTED_DRIVER_PROC_SYMBOLS | EXPECTED_DRIVER_PROC_UNSUPPORTED_SYMBOLS
    if not proc_contract <= EXPECTED_DRIVER_SYMBOLS:
        raise AssertionError(
            "driver proc-address contract references non-exported symbols: "
            f"{sorted(proc_contract - EXPECTED_DRIVER_SYMBOLS)}"
        )


def c_string(value: bytes | None) -> str:
    if value is None:
        raise AssertionError("expected a non-null C string")
    return value.decode("utf-8")


def cu_get_proc_address(libcuda: ctypes.CDLL, symbol: bytes) -> tuple[int, int, int | None]:
    proc = ctypes.c_void_p(123)
    status = ctypes.c_int(-1)
    result = libcuda.cuGetProcAddress(
        symbol,
        ctypes.byref(proc),
        0,
        0,
        ctypes.byref(status),
    )
    return result, status.value, proc.value


def buffer_ptr(buffer: ctypes.Array[ctypes.c_char]) -> ctypes.c_void_p:
    return ctypes.cast(buffer, ctypes.c_void_p)


def void_p_value(ptr: ctypes.c_void_p | int | None) -> int | None:
    if isinstance(ptr, ctypes.c_void_p):
        return ptr.value
    return ptr


def pointer_offset(ptr: ctypes.c_void_p, offset: int) -> ctypes.c_void_p:
    if ptr.value is None:
        raise AssertionError("expected a non-null pointer")
    return ctypes.c_void_p(ptr.value + offset)


def cuda_launch_params(*storages: object) -> ctypes.Array[ctypes.c_void_p]:
    return (ctypes.c_void_p * len(storages))(
        *[ctypes.cast(ctypes.byref(storage), ctypes.c_void_p) for storage in storages]
    )


def assert_near(actual: float, expected: float, label: str, *, rel_tol: float = 1e-6, abs_tol: float = 1e-6) -> None:
    if not math.isclose(actual, expected, rel_tol=rel_tol, abs_tol=abs_tol):
        raise AssertionError(f"{label}: expected {expected}, got {actual}")


def complex_pair(value: CuComplex | CuDoubleComplex) -> tuple[float, float]:
    return (round(float(value.x), 5), round(float(value.y), 5))


def complex_list(values: object) -> list[tuple[float, float]]:
    return [complex_pair(value) for value in values]


def complex_array(element_type: type[CuComplex] | type[CuDoubleComplex], pairs: list[tuple[float, float]]):
    return (element_type * len(pairs))(*(element_type(float(real), float(imag)) for real, imag in pairs))


def complex_values(values: object) -> list[complex]:
    return [complex(float(value.x), float(value.y)) for value in values]


def complex_matrix_values(values: object, *, rows: int, cols: int, ld: int) -> list[object]:
    return [values[row + col * ld] for col in range(cols) for row in range(rows)]


def real_matrix_values(values: object, *, rows: int, cols: int, ld: int) -> list[float]:
    return [float(values[row + col * ld]) for col in range(cols) for row in range(rows)]


def real_layout_value(values: list[float], *, order: int, row: int, col: int, ld: int) -> float:
    if order == CUBLASLT_ORDER_ROW:
        return values[row * ld + col]
    return values[row + col * ld]


def real_layout_matrix_values(values: object, *, rows: int, cols: int, ld: int, order: int) -> list[float]:
    raw = [float(value) for value in values]
    return [real_layout_value(raw, order=order, row=row, col=col, ld=ld) for col in range(cols) for row in range(rows)]


def real_layout_op_value(values: object, *, order: int, op: int, row: int, col: int, ld: int) -> float:
    raw = [float(value) for value in values]
    if op == CUBLAS_OP_N:
        return real_layout_value(raw, order=order, row=row, col=col, ld=ld)
    return real_layout_value(raw, order=order, row=col, col=row, ld=ld)


def real_layout_bgrada(values: object, *, rows: int, k: int, ld: int, order: int, transa: int) -> list[float]:
    return [
        sum(real_layout_op_value(values, order=order, op=transa, row=row, col=inner, ld=ld) for inner in range(k))
        for row in range(rows)
    ]


def real_layout_bgradb(values: object, *, cols: int, k: int, ld: int, order: int, transb: int) -> list[float]:
    return [
        sum(real_layout_op_value(values, order=order, op=transb, row=inner, col=col, ld=ld) for inner in range(k))
        for col in range(cols)
    ]


def real_layout_gemm(
    a_values: object,
    b_values: object,
    c_values: object,
    *,
    transa: int,
    transb: int,
    m: int,
    n: int,
    k: int,
    lda: int,
    ldb: int,
    ldc: int,
    a_order: int,
    b_order: int,
    c_order: int,
    alpha: float,
    beta: float,
) -> list[float]:
    a = [float(value) for value in a_values]
    b = [float(value) for value in b_values]
    c = [float(value) for value in c_values]

    def op_value(values: list[float], order: int, op: int, row: int, col: int, ld: int) -> float:
        if op == CUBLAS_OP_N:
            return real_layout_value(values, order=order, row=row, col=col, ld=ld)
        return real_layout_value(values, order=order, row=col, col=row, ld=ld)

    out: list[float] = []
    for col in range(n):
        for row in range(m):
            acc = 0.0
            for inner in range(k):
                acc += op_value(a, a_order, transa, row, inner, lda) * op_value(b, b_order, transb, inner, col, ldb)
            prior = 0.0 if beta == 0 else beta * real_layout_value(c, order=c_order, row=row, col=col, ld=ldc)
            out.append(alpha * acc + prior)
    return out


def real_column_major_gemm(
    a_values: object,
    b_values: object,
    c_values: object,
    *,
    transa: int,
    transb: int,
    m: int,
    n: int,
    k: int,
    lda: int,
    ldb: int,
    ldc: int,
    alpha: float,
    beta: float,
) -> list[float]:
    a = [float(value) for value in a_values]
    b = [float(value) for value in b_values]
    c = [float(value) for value in c_values]

    def op_value(values: list[float], op: int, row: int, col: int, ld: int) -> float:
        return values[row + col * ld] if op == CUBLAS_OP_N else values[col + row * ld]

    out: list[float] = []
    for col in range(n):
        for row in range(m):
            acc = 0.0
            for inner in range(k):
                acc += op_value(a, transa, row, inner, lda) * op_value(b, transb, inner, col, ldb)
            out.append(alpha * acc + (0.0 if beta == 0 else beta * c[row + col * ldc]))
    return out


def complex_column_major_gemm(
    a_values: object,
    b_values: object,
    c_values: object,
    *,
    transa: int,
    transb: int,
    m: int,
    n: int,
    k: int,
    lda: int,
    ldb: int,
    ldc: int,
    alpha: complex,
    beta: complex,
) -> list[complex]:
    a = complex_values(a_values)
    b = complex_values(b_values)
    c = complex_values(c_values)

    def op_value(values: list[complex], op: int, row: int, col: int, ld: int) -> complex:
        value = values[row + col * ld] if op == CUBLAS_OP_N else values[col + row * ld]
        return value.conjugate() if op == CUBLAS_OP_C else value

    out: list[complex] = []
    for col in range(n):
        for row in range(m):
            acc = 0j
            for inner in range(k):
                acc += op_value(a, transa, row, inner, lda) * op_value(b, transb, inner, col, ldb)
            out.append(alpha * acc + (0j if beta == 0 else beta * c[row + col * ldc]))
    return out


def signed_stride_index(length: int, inc: int, index: int) -> int:
    if inc == 0:
        raise ValueError("zero stride has no logical index")
    abs_inc = abs(inc)
    return index * abs_inc if inc > 0 else (length - 1 - index) * abs_inc


def check_signed_stride_index_oracle() -> None:
    if [signed_stride_index(3, -2, index) for index in range(3)] != [4, 2, 0]:
        raise AssertionError("negative signed-stride indexing should keep the base pointer at storage offset 0")
    if [signed_stride_index(3, 2, index) for index in range(3)] != [0, 2, 4]:
        raise AssertionError("positive signed-stride indexing should advance from storage offset 0")


def complex_column_major_gemv(
    a_values: object,
    x_values: object,
    y_values: object,
    *,
    trans: int,
    m: int,
    n: int,
    lda: int,
    incx: int,
    incy: int,
    alpha: complex,
    beta: complex,
) -> list[complex]:
    a = complex_values(a_values)
    x = complex_values(x_values)
    y = complex_values(y_values)
    input_len = n if trans == CUBLAS_OP_N else m
    output_len = m if trans == CUBLAS_OP_N else n

    def op_value(out: int, inner: int) -> complex:
        value = a[out + inner * lda] if trans == CUBLAS_OP_N else a[inner + out * lda]
        return value.conjugate() if trans == CUBLAS_OP_C else value

    out_values: list[complex] = []
    for out in range(output_len):
        acc = 0j
        for inner in range(input_len):
            acc += op_value(out, inner) * x[signed_stride_index(input_len, incx, inner)]
        out_values.append(alpha * acc + (0j if beta == 0 else beta * y[signed_stride_index(output_len, incy, out)]))
    return out_values


def float_column_major_gemv(
    a_values: object,
    x_values: object,
    y_values: object,
    *,
    trans: int,
    m: int,
    n: int,
    lda: int,
    incx: int,
    incy: int,
    alpha: float,
    beta: float,
) -> list[float]:
    input_len = n if trans == CUBLAS_OP_N else m
    output_len = m if trans == CUBLAS_OP_N else n
    out_values: list[float] = []
    for out in range(output_len):
        acc = 0.0
        for inner in range(input_len):
            a_index = out + inner * lda if trans == CUBLAS_OP_N else inner + out * lda
            acc += float(a_values[a_index]) * float(x_values[signed_stride_index(input_len, incx, inner)])
        out_values.append(alpha * acc + (0.0 if beta == 0 else beta * float(y_values[signed_stride_index(output_len, incy, out)])))
    return out_values


def float_column_major_ger(
    a_values: object,
    x_values: object,
    y_values: object,
    *,
    m: int,
    n: int,
    lda: int,
    incx: int,
    incy: int,
    alpha: float,
) -> list[float]:
    out = [float(value) for value in a_values]
    for col in range(n):
        scaled_y = alpha * float(y_values[signed_stride_index(n, incy, col)])
        for row in range(m):
            out[row + col * lda] += float(x_values[signed_stride_index(m, incx, row)]) * scaled_y
    return out


def complex_column_major_ger(
    a_values: object,
    x_values: object,
    y_values: object,
    *,
    m: int,
    n: int,
    lda: int,
    incx: int,
    incy: int,
    alpha: complex,
    conjugate_y: bool,
) -> list[complex]:
    a = complex_values(a_values)
    x = complex_values(x_values)
    y = complex_values(y_values)
    out = list(a)
    for col in range(n):
        y_value = y[signed_stride_index(n, incy, col)]
        y_value = y_value.conjugate() if conjugate_y else y_value
        scaled_y = alpha * y_value
        for row in range(m):
            out[row + col * lda] += x[signed_stride_index(m, incx, row)] * scaled_y
    return [out[row + col * lda] for col in range(n) for row in range(m)]


def complex_column_major_hemv(
    a_values: object,
    x_values: object,
    y_values: object,
    *,
    uplo: int,
    n: int,
    lda: int,
    incx: int,
    incy: int,
    alpha: complex,
    beta: complex,
) -> list[complex]:
    a = complex_values(a_values)
    x = complex_values(x_values)
    y = complex_values(y_values)

    def hermitian_value(row: int, col: int) -> complex:
        if row == col:
            return complex(a[row + col * lda].real, 0.0)
        stored = row >= col if uplo == CUBLAS_FILL_MODE_LOWER else row <= col
        if stored:
            return a[row + col * lda]
        return a[col + row * lda].conjugate()

    out: list[complex] = []
    for row in range(n):
        acc = 0j
        for col in range(n):
            acc += hermitian_value(row, col) * x[signed_stride_index(n, incx, col)]
        y_value = 0j if beta == 0j else y[signed_stride_index(n, incy, row)]
        out.append(alpha * acc + beta * y_value)
    return out


def complex_column_major_her(
    a_values: object,
    x_values: object,
    *,
    uplo: int,
    n: int,
    lda: int,
    incx: int,
    alpha: float,
) -> list[complex]:
    a = complex_values(a_values)
    x = complex_values(x_values)
    out = list(a)
    for col in range(n):
        for row in range(n):
            stored = row >= col if uplo == CUBLAS_FILL_MODE_LOWER else row <= col
            if not stored:
                continue
            index = row + col * lda
            if row == col:
                out[index] = complex(out[index].real + alpha * abs(x[signed_stride_index(n, incx, row)]) ** 2, 0.0)
            else:
                out[index] += alpha * x[signed_stride_index(n, incx, row)] * x[signed_stride_index(n, incx, col)].conjugate()
    return [out[row + col * lda] for col in range(n) for row in range(n)]


def complex_column_major_her2(
    a_values: object,
    x_values: object,
    y_values: object,
    *,
    uplo: int,
    n: int,
    lda: int,
    incx: int,
    incy: int,
    alpha: complex,
) -> list[complex]:
    a = complex_values(a_values)
    x = complex_values(x_values)
    y = complex_values(y_values)
    out = list(a)
    for col in range(n):
        for row in range(n):
            stored = row >= col if uplo == CUBLAS_FILL_MODE_LOWER else row <= col
            if not stored:
                continue
            index = row + col * lda
            x_row = x[signed_stride_index(n, incx, row)]
            x_col = x[signed_stride_index(n, incx, col)]
            y_row = y[signed_stride_index(n, incy, row)]
            y_col = y[signed_stride_index(n, incy, col)]
            out[index] += alpha * x_row * y_col.conjugate() + alpha.conjugate() * y_row * x_col.conjugate()
            if row == col:
                out[index] = complex(out[index].real, 0.0)
    return [out[row + col * lda] for col in range(n) for row in range(n)]


def complex_column_major_herk(
    c_values: object,
    a_values: object,
    *,
    uplo: int,
    trans: int,
    n: int,
    k: int,
    lda: int,
    ldc: int,
    alpha: float,
    beta: float,
) -> list[complex]:
    c = complex_values(c_values)
    a = complex_values(a_values)
    out = list(c)

    def op_value(row: int, inner: int) -> complex:
        if trans == CUBLAS_OP_N:
            return a[row + inner * lda]
        value = a[inner + row * lda]
        return value.conjugate() if trans == CUBLAS_OP_C else value

    for col in range(n):
        for row in range(n):
            stored = row >= col if uplo == CUBLAS_FILL_MODE_LOWER else row <= col
            if not stored:
                continue
            index = row + col * ldc
            product = 0j
            if alpha != 0.0 and k > 0:
                for inner in range(k):
                    product += op_value(row, inner) * op_value(col, inner).conjugate()
                product *= alpha
            if beta == 0.0:
                existing = 0j
            elif row == col:
                existing = complex(beta * c[index].real, 0.0)
            else:
                existing = beta * c[index]
            value = product + existing
            out[index] = complex(value.real, 0.0) if row == col else value
    return [out[row + col * ldc] for col in range(n) for row in range(n)]


def complex_column_major_her2k(
    c_values: object,
    a_values: object,
    b_values: object,
    *,
    uplo: int,
    trans: int,
    n: int,
    k: int,
    lda: int,
    ldb: int,
    ldc: int,
    alpha: complex,
    beta: float,
) -> list[complex]:
    c = complex_values(c_values)
    a = complex_values(a_values)
    b = complex_values(b_values)
    out = list(c)

    def op_value(values: list[complex], ld: int, row: int, inner: int) -> complex:
        if trans == CUBLAS_OP_N:
            return values[row + inner * ld]
        value = values[inner + row * ld]
        return value.conjugate() if trans == CUBLAS_OP_C else value

    for col in range(n):
        for row in range(n):
            stored = row >= col if uplo == CUBLAS_FILL_MODE_LOWER else row <= col
            if not stored:
                continue
            index = row + col * ldc
            product = 0j
            if alpha != 0j and k > 0:
                acc_ab = 0j
                acc_ba = 0j
                for inner in range(k):
                    acc_ab += op_value(a, lda, row, inner) * op_value(b, ldb, col, inner).conjugate()
                    acc_ba += op_value(b, ldb, row, inner) * op_value(a, lda, col, inner).conjugate()
                product = alpha * acc_ab + alpha.conjugate() * acc_ba
            if beta == 0.0:
                existing = 0j
            elif row == col:
                existing = complex(beta * c[index].real, 0.0)
            else:
                existing = beta * c[index]
            value = product + existing
            out[index] = complex(value.real, 0.0) if row == col else value
    return [out[row + col * ldc] for col in range(n) for row in range(n)]


def complex_column_major_trmv(
    a_values: object,
    x_values: object,
    *,
    uplo: int,
    trans: int,
    diag: int,
    n: int,
    lda: int,
    incx: int,
) -> list[complex]:
    a = complex_values(a_values)
    x = complex_values(x_values)

    def triangular_value(row: int, col: int) -> complex:
        source_row = row if trans == CUBLAS_OP_N else col
        source_col = col if trans == CUBLAS_OP_N else row
        stored = source_row >= source_col if uplo == CUBLAS_FILL_MODE_LOWER else source_row <= source_col
        if not stored:
            return 0j
        if source_row == source_col and diag == CUBLAS_DIAG_UNIT:
            return 1 + 0j
        value = a[source_row + source_col * lda]
        return value.conjugate() if trans == CUBLAS_OP_C else value

    out: list[complex] = []
    for row in range(n):
        acc = 0j
        for col in range(n):
            acc += triangular_value(row, col) * x[signed_stride_index(n, incx, col)]
        out.append(acc)
    return out


def complex_column_major_trsv(
    a_values: object,
    x_values: object,
    *,
    uplo: int,
    trans: int,
    diag: int,
    n: int,
    lda: int,
    incx: int,
) -> list[complex]:
    a = complex_values(a_values)
    x = complex_values(x_values)

    def triangular_value(row: int, col: int) -> complex:
        source_row = row if trans == CUBLAS_OP_N else col
        source_col = col if trans == CUBLAS_OP_N else row
        stored = source_row >= source_col if uplo == CUBLAS_FILL_MODE_LOWER else source_row <= source_col
        if not stored:
            return 0j
        if source_row == source_col and diag == CUBLAS_DIAG_UNIT:
            return 1 + 0j
        value = a[source_row + source_col * lda]
        return value.conjugate() if trans == CUBLAS_OP_C else value

    tmp = [x[signed_stride_index(n, incx, row)] for row in range(n)]
    op_is_lower = uplo == CUBLAS_FILL_MODE_LOWER if trans == CUBLAS_OP_N else uplo == CUBLAS_FILL_MODE_UPPER
    if op_is_lower:
        for row in range(n):
            value = tmp[row]
            for col in range(row):
                value -= triangular_value(row, col) * tmp[col]
            if diag == CUBLAS_DIAG_NON_UNIT:
                value /= triangular_value(row, row)
            tmp[row] = value
    else:
        for row in range(n - 1, -1, -1):
            value = tmp[row]
            for col in range(row + 1, n):
                value -= triangular_value(row, col) * tmp[col]
            if diag == CUBLAS_DIAG_NON_UNIT:
                value /= triangular_value(row, row)
            tmp[row] = value
    return tmp


def complex_column_major_trmm(
    a_values: object,
    b_values: object,
    *,
    side: int,
    uplo: int,
    trans: int,
    diag: int,
    m: int,
    n: int,
    lda: int,
    ldb: int,
    alpha: complex,
) -> list[complex]:
    a = complex_values(a_values)
    b = complex_values(b_values)

    def triangular_value(row: int, col: int) -> complex:
        source_row = row if trans == CUBLAS_OP_N else col
        source_col = col if trans == CUBLAS_OP_N else row
        stored = source_row >= source_col if uplo == CUBLAS_FILL_MODE_LOWER else source_row <= source_col
        if not stored:
            return 0j
        if source_row == source_col and diag == CUBLAS_DIAG_UNIT:
            return 1 + 0j
        value = a[source_row + source_col * lda]
        return value.conjugate() if trans == CUBLAS_OP_C else value

    out: list[complex] = []
    for col in range(n):
        for row in range(m):
            acc = 0j
            if side == CUBLAS_SIDE_LEFT:
                for inner in range(m):
                    acc += triangular_value(row, inner) * b[inner + col * ldb]
            else:
                for inner in range(n):
                    acc += b[row + inner * ldb] * triangular_value(inner, col)
            out.append(alpha * acc)
    return out


def complex_column_major_trsm(
    a_values: object,
    b_values: object,
    *,
    side: int,
    uplo: int,
    trans: int,
    diag: int,
    m: int,
    n: int,
    lda: int,
    ldb: int,
    alpha: complex,
) -> list[complex]:
    a = complex_values(a_values)
    b = complex_values(b_values)

    def triangular_value(row: int, col: int) -> complex:
        source_row = row if trans == CUBLAS_OP_N else col
        source_col = col if trans == CUBLAS_OP_N else row
        stored = source_row >= source_col if uplo == CUBLAS_FILL_MODE_LOWER else source_row <= source_col
        if not stored:
            return 0j
        if source_row == source_col and diag == CUBLAS_DIAG_UNIT:
            return 1 + 0j
        value = a[source_row + source_col * lda]
        return value.conjugate() if trans == CUBLAS_OP_C else value

    tmp = [0j] * (m * n)
    for col in range(n):
        for row in range(m):
            tmp[row + col * m] = alpha * b[row + col * ldb]

    op_is_lower = uplo == CUBLAS_FILL_MODE_LOWER if trans == CUBLAS_OP_N else uplo == CUBLAS_FILL_MODE_UPPER
    if side == CUBLAS_SIDE_LEFT:
        if op_is_lower:
            for col in range(n):
                for row in range(m):
                    value = tmp[row + col * m]
                    for inner in range(row):
                        value -= triangular_value(row, inner) * tmp[inner + col * m]
                    if diag == CUBLAS_DIAG_NON_UNIT:
                        value /= triangular_value(row, row)
                    tmp[row + col * m] = value
        else:
            for col in range(n):
                for row in range(m - 1, -1, -1):
                    value = tmp[row + col * m]
                    for inner in range(row + 1, m):
                        value -= triangular_value(row, inner) * tmp[inner + col * m]
                    if diag == CUBLAS_DIAG_NON_UNIT:
                        value /= triangular_value(row, row)
                    tmp[row + col * m] = value
    else:
        for row in range(m):
            if op_is_lower:
                for col in range(n - 1, -1, -1):
                    value = tmp[row + col * m]
                    for inner in range(col + 1, n):
                        value -= tmp[row + inner * m] * triangular_value(inner, col)
                    if diag == CUBLAS_DIAG_NON_UNIT:
                        value /= triangular_value(col, col)
                    tmp[row + col * m] = value
            else:
                for col in range(n):
                    value = tmp[row + col * m]
                    for inner in range(col):
                        value -= tmp[row + inner * m] * triangular_value(inner, col)
                    if diag == CUBLAS_DIAG_NON_UNIT:
                        value /= triangular_value(col, col)
                    tmp[row + col * m] = value
    return tmp


def assert_complex_values_near(
    actual: object,
    expected: list[complex],
    label: str,
    *,
    rel_tol: float = 1e-5,
    abs_tol: float = 1e-5,
) -> None:
    actual_values = complex_values(actual)
    if len(actual_values) != len(expected):
        raise AssertionError(f"{label}: expected {len(expected)} values, got {len(actual_values)}")
    for idx, (actual_value, expected_value) in enumerate(zip(actual_values, expected, strict=True)):
        assert_near(actual_value.real, expected_value.real, f"{label}[{idx}].real", rel_tol=rel_tol, abs_tol=abs_tol)
        assert_near(actual_value.imag, expected_value.imag, f"{label}[{idx}].imag", rel_tol=rel_tol, abs_tol=abs_tol)


def assert_real_values_near(
    actual: list[float],
    expected: list[float],
    label: str,
    *,
    rel_tol: float = 1e-5,
    abs_tol: float = 1e-5,
) -> None:
    if len(actual) != len(expected):
        raise AssertionError(f"{label}: expected {len(expected)} values, got {len(actual)}")
    for idx, (actual_value, expected_value) in enumerate(zip(actual, expected, strict=True)):
        assert_near(actual_value, expected_value, f"{label}[{idx}]", rel_tol=rel_tol, abs_tol=abs_tol)


def gelu_tanh_approx(value: float) -> float:
    if math.isnan(value):
        return math.nan
    if math.isinf(value):
        return value if value > 0.0 else 0.0
    return 0.5 * value * (1.0 + math.tanh(math.sqrt(2.0 / math.pi) * (value + 0.044715 * value * value * value)))


def gelu_tanh_grad_approx(value: float) -> float:
    if math.isnan(value):
        return math.nan
    if math.isinf(value):
        return 1.0 if value > 0.0 else 0.0
    root = math.sqrt(2.0 / math.pi)
    inner = root * (value + 0.044715 * value * value * value)
    tanh_inner = math.tanh(inner)
    sech2 = 1.0 - tanh_inner * tanh_inner
    return 0.5 * (1.0 + tanh_inner) + 0.5 * value * sech2 * root * (1.0 + 3.0 * 0.044715 * value * value)


def relu_active(value: float) -> bool:
    return value > 0.0


def relu_aux_get_bit(mask: object, bit_index: int) -> int:
    return (int(mask[bit_index // 8]) >> (bit_index & 7)) & 1


def relu_aux_live_bits(mask: object, *, rows: int, cols: int, aux_ld: int) -> list[int]:
    return [relu_aux_get_bit(mask, row + col * aux_ld) for col in range(cols) for row in range(rows)]


def assert_real_values_close_or_nan(
    actual: list[float],
    expected: list[float],
    label: str,
    *,
    rel_tol: float = 1e-5,
    abs_tol: float = 1e-6,
) -> None:
    if len(actual) != len(expected):
        raise AssertionError(f"{label}: expected {len(expected)} values, got {len(actual)}")
    for idx, (actual_value, expected_value) in enumerate(zip(actual, expected, strict=True)):
        if math.isnan(expected_value):
            if not math.isnan(actual_value):
                raise AssertionError(f"{label}[{idx}]: expected NaN, got {actual_value}")
        elif math.isinf(expected_value):
            if not math.isinf(actual_value) or (actual_value > 0.0) != (expected_value > 0.0):
                raise AssertionError(f"{label}[{idx}]: expected {expected_value}, got {actual_value}")
        else:
            assert_near(actual_value, expected_value, f"{label}[{idx}]", rel_tol=rel_tol, abs_tol=abs_tol)


def reference_rotmg(d1: float, d2: float, x1: float, y1: float, param: list[float]) -> tuple[float, float, float, list[float]]:
    zero = 0.0
    one = 1.0
    two = 2.0
    gam = 4096.0
    gamsq = 16777216.0
    rgamsq = 5.9604644775390625e-8
    flag = 0.0
    h11 = h12 = h21 = h22 = 0.0
    out_param = list(param)
    if d1 < zero:
        flag = -one
        d1 = d2 = x1 = zero
    else:
        p2 = d2 * y1
        if p2 == zero:
            out_param[0] = -two
            return d1, d2, x1, out_param
        p1 = d1 * x1
        q2 = p2 * y1
        q1 = p1 * x1
        if abs(q1) > abs(q2):
            h21 = -y1 / x1
            h12 = p2 / p1
            u = one - h12 * h21
            if u > zero:
                flag = zero
                d1 = d1 / u
                d2 = d2 / u
                x1 = x1 * u
            else:
                flag = -one
                h11 = h12 = h21 = h22 = zero
                d1 = d2 = x1 = zero
        elif q2 < zero:
            flag = -one
            h11 = h12 = h21 = h22 = zero
            d1 = d2 = x1 = zero
        else:
            flag = one
            h11 = p1 / p2
            h22 = x1 / y1
            u = one + h11 * h22
            temp = d2 / u
            d2 = d1 / u
            d1 = temp
            x1 = y1 * u
        if d1 != zero and math.isfinite(d1):
            while d1 <= rgamsq or d1 >= gamsq:
                if flag == zero:
                    h11 = one
                    h22 = one
                    flag = -one
                else:
                    h21 = -one
                    h12 = one
                    flag = -one
                if d1 <= rgamsq:
                    d1 = d1 * gam * gam
                    x1 = x1 / gam
                    h11 = h11 / gam
                    h12 = h12 / gam
                else:
                    d1 = d1 / (gam * gam)
                    x1 = x1 * gam
                    h11 = h11 * gam
                    h12 = h12 * gam
        if d2 != zero and math.isfinite(d2):
            while abs(d2) <= rgamsq or abs(d2) >= gamsq:
                if flag == zero:
                    h11 = one
                    h22 = one
                    flag = -one
                else:
                    h21 = -one
                    h12 = one
                    flag = -one
                if abs(d2) <= rgamsq:
                    d2 = d2 * gam * gam
                    h21 = h21 / gam
                    h22 = h22 / gam
                else:
                    d2 = d2 / (gam * gam)
                    h21 = h21 * gam
                    h22 = h22 * gam
    if flag < zero:
        out_param[1] = h11
        out_param[2] = h21
        out_param[3] = h12
        out_param[4] = h22
    elif flag == zero:
        out_param[2] = h21
        out_param[3] = h12
    else:
        out_param[1] = h11
        out_param[4] = h22
    out_param[0] = flag
    return d1, d2, x1, out_param


def deviceptr_offset(ptr: ctypes.c_ulonglong, offset: int) -> ctypes.c_ulonglong:
    if ptr.value == 0:
        raise AssertionError("expected a non-zero device pointer")
    return ctypes.c_ulonglong(ptr.value + offset)


def buffer_deviceptr(buffer: ctypes.Array[ctypes.c_char]) -> ctypes.c_ulonglong:
    return ctypes.c_ulonglong(buffer_ptr(buffer).value)


def check_cuda_memcpy2d_ctypes_layout() -> None:
    expected_offsets = {
        "srcXInBytes": 0,
        "srcY": 8,
        "srcMemoryType": 16,
        "srcHost": 24,
        "srcDevice": 32,
        "srcArray": 40,
        "srcPitch": 48,
        "dstXInBytes": 56,
        "dstY": 64,
        "dstMemoryType": 72,
        "dstHost": 80,
        "dstDevice": 88,
        "dstArray": 96,
        "dstPitch": 104,
        "WidthInBytes": 112,
        "Height": 120,
    }
    if ctypes.sizeof(CUDA_MEMCPY2D) != 128:
        raise AssertionError(f"CUDA_MEMCPY2D ctypes size drifted to {ctypes.sizeof(CUDA_MEMCPY2D)}")
    for field_name, expected in expected_offsets.items():
        got = getattr(CUDA_MEMCPY2D, field_name).offset
        if got != expected:
            raise AssertionError(f"CUDA_MEMCPY2D ctypes offset for {field_name} is {got}, expected {expected}")


def check_cuda_memcpy3d_ctypes_layout() -> None:
    expected_offsets = {
        "srcXInBytes": 0,
        "srcY": 8,
        "srcZ": 16,
        "srcLOD": 24,
        "srcMemoryType": 32,
        "srcHost": 40,
        "srcDevice": 48,
        "srcArray": 56,
        "reserved0": 64,
        "srcPitch": 72,
        "srcHeight": 80,
        "dstXInBytes": 88,
        "dstY": 96,
        "dstZ": 104,
        "dstLOD": 112,
        "dstMemoryType": 120,
        "dstHost": 128,
        "dstDevice": 136,
        "dstArray": 144,
        "reserved1": 152,
        "dstPitch": 160,
        "dstHeight": 168,
        "WidthInBytes": 176,
        "Height": 184,
        "Depth": 192,
    }
    if ctypes.sizeof(CUDA_MEMCPY3D) != 200:
        raise AssertionError(f"CUDA_MEMCPY3D ctypes size drifted to {ctypes.sizeof(CUDA_MEMCPY3D)}")
    for field_name, expected in expected_offsets.items():
        got = getattr(CUDA_MEMCPY3D, field_name).offset
        if got != expected:
            raise AssertionError(f"CUDA_MEMCPY3D ctypes offset for {field_name} is {got}, expected {expected}")
    if ctypes.sizeof(CudaPitchedPtr) != 32:
        raise AssertionError(f"cudaPitchedPtr ctypes size drifted to {ctypes.sizeof(CudaPitchedPtr)}")
    if ctypes.sizeof(CudaExtent) != 24:
        raise AssertionError(f"cudaExtent ctypes size drifted to {ctypes.sizeof(CudaExtent)}")
    if ctypes.sizeof(CudaPos) != 24:
        raise AssertionError(f"cudaPos ctypes size drifted to {ctypes.sizeof(CudaPos)}")
    if ctypes.sizeof(CudaMemcpy3DParms) != 160:
        raise AssertionError(f"cudaMemcpy3DParms ctypes size drifted to {ctypes.sizeof(CudaMemcpy3DParms)}")
    expected_runtime_offsets = {
        "srcArray": 0,
        "srcPos": 8,
        "srcPtr": 32,
        "dstArray": 64,
        "dstPos": 72,
        "dstPtr": 96,
        "extent": 128,
        "kind": 152,
    }
    for field_name, expected in expected_runtime_offsets.items():
        got = getattr(CudaMemcpy3DParms, field_name).offset
        if got != expected:
            raise AssertionError(f"cudaMemcpy3DParms ctypes offset for {field_name} is {got}, expected {expected}")


def check_cuda_pointer_attributes_ctypes_layout() -> None:
    if ctypes.sizeof(CudaPointerAttributes) != 96:
        raise AssertionError(
            f"cudaPointerAttributes ctypes size drifted to {ctypes.sizeof(CudaPointerAttributes)}"
        )
    expected_offsets = {
        "device": 0,
        "devicePointer": 8,
        "hostPointer": 16,
        "reserved": 24,
        "type": 88,
    }
    for field_name, expected in expected_offsets.items():
        got = getattr(CudaPointerAttributes, field_name).offset
        if got != expected:
            raise AssertionError(
                f"cudaPointerAttributes ctypes offset for {field_name} is {got}, expected {expected}"
            )


def check_cuda_memory_pool_ctypes_layout() -> None:
    for struct_name, struct_type in (
        ("CUmemLocation", CUmemLocation),
        ("cudaMemLocation", CudaMemLocation),
    ):
        if ctypes.sizeof(struct_type) != 8:
            raise AssertionError(f"{struct_name} ctypes size drifted to {ctypes.sizeof(struct_type)}")
        expected_offsets = {"id": 0, "type": 4}
        for field_name, expected in expected_offsets.items():
            got = getattr(struct_type, field_name).offset
            if got != expected:
                raise AssertionError(
                    f"{struct_name} ctypes offset for {field_name} is {got}, expected {expected}"
                )

    for struct_name, struct_type in (
        ("CUmemPoolProps", CUmemPoolProps),
        ("cudaMemPoolProps", CudaMemPoolProps),
    ):
        if ctypes.sizeof(struct_type) != 88:
            raise AssertionError(f"{struct_name} ctypes size drifted to {ctypes.sizeof(struct_type)}")
        expected_offsets = {
            "allocType": 0,
            "handleTypes": 4,
            "location": 8,
            "maxSize": 16,
            "reserved": 24,
            "usage": 78,
            "win32SecurityAttributes": 80,
        }
        for field_name, expected in expected_offsets.items():
            got = getattr(struct_type, field_name).offset
            if got != expected:
                raise AssertionError(
                    f"{struct_name} ctypes offset for {field_name} is {got}, expected {expected}"
                )


def cuda_memcpy2d(
    *,
    src_memory_type: int,
    dst_memory_type: int,
    width: int,
    height: int,
    src_pitch: int,
    dst_pitch: int,
    src_host: ctypes.c_void_p | None = None,
    dst_host: ctypes.c_void_p | None = None,
    src_device: ctypes.c_ulonglong | int = 0,
    dst_device: ctypes.c_ulonglong | int = 0,
    src_x: int = 0,
    src_y: int = 0,
    dst_x: int = 0,
    dst_y: int = 0,
) -> CUDA_MEMCPY2D:
    copy = CUDA_MEMCPY2D()
    copy.srcXInBytes = src_x
    copy.srcY = src_y
    copy.srcMemoryType = src_memory_type
    copy.srcHost = src_host
    copy.srcDevice = src_device.value if isinstance(src_device, ctypes.c_ulonglong) else src_device
    copy.srcArray = None
    copy.srcPitch = src_pitch
    copy.dstXInBytes = dst_x
    copy.dstY = dst_y
    copy.dstMemoryType = dst_memory_type
    copy.dstHost = dst_host
    copy.dstDevice = dst_device.value if isinstance(dst_device, ctypes.c_ulonglong) else dst_device
    copy.dstArray = None
    copy.dstPitch = dst_pitch
    copy.WidthInBytes = width
    copy.Height = height
    return copy


def cuda_memcpy3d(
    *,
    src_memory_type: int,
    dst_memory_type: int,
    width: int,
    height: int,
    depth: int,
    src_pitch: int,
    src_height: int,
    dst_pitch: int,
    dst_height: int,
    src_host: ctypes.c_void_p | None = None,
    dst_host: ctypes.c_void_p | None = None,
    src_device: ctypes.c_ulonglong | int = 0,
    dst_device: ctypes.c_ulonglong | int = 0,
    src_x: int = 0,
    src_y: int = 0,
    src_z: int = 0,
    dst_x: int = 0,
    dst_y: int = 0,
    dst_z: int = 0,
) -> CUDA_MEMCPY3D:
    copy = CUDA_MEMCPY3D()
    copy.srcXInBytes = src_x
    copy.srcY = src_y
    copy.srcZ = src_z
    copy.srcLOD = 0
    copy.srcMemoryType = src_memory_type
    copy.srcHost = src_host
    copy.srcDevice = src_device.value if isinstance(src_device, ctypes.c_ulonglong) else src_device
    copy.srcArray = None
    copy.reserved0 = None
    copy.srcPitch = src_pitch
    copy.srcHeight = src_height
    copy.dstXInBytes = dst_x
    copy.dstY = dst_y
    copy.dstZ = dst_z
    copy.dstLOD = 0
    copy.dstMemoryType = dst_memory_type
    copy.dstHost = dst_host
    copy.dstDevice = dst_device.value if isinstance(dst_device, ctypes.c_ulonglong) else dst_device
    copy.dstArray = None
    copy.reserved1 = None
    copy.dstPitch = dst_pitch
    copy.dstHeight = dst_height
    copy.WidthInBytes = width
    copy.Height = height
    copy.Depth = depth
    return copy


def cuda_memcpy3d_params(
    *,
    src_ptr: ctypes.c_void_p | None,
    dst_ptr: ctypes.c_void_p | None,
    width: int,
    height: int,
    depth: int,
    src_pitch: int,
    src_height: int,
    dst_pitch: int,
    dst_height: int,
    kind: int,
    src_x: int = 0,
    src_y: int = 0,
    src_z: int = 0,
    dst_x: int = 0,
    dst_y: int = 0,
    dst_z: int = 0,
) -> CudaMemcpy3DParms:
    params = CudaMemcpy3DParms()
    params.srcArray = None
    params.srcPos = CudaPos(src_x, src_y, src_z)
    params.srcPtr = CudaPitchedPtr(void_p_value(src_ptr), src_pitch, src_pitch, src_height)
    params.dstArray = None
    params.dstPos = CudaPos(dst_x, dst_y, dst_z)
    params.dstPtr = CudaPitchedPtr(void_p_value(dst_ptr), dst_pitch, dst_pitch, dst_height)
    params.extent = CudaExtent(width, height, depth)
    params.kind = kind
    return params


