        if libcuda.cuMemcpyHtoD(out_dev, ctypes.cast(zero_host, ctypes.c_void_p), vector_bytes) != CUDA_SUCCESS:
            raise AssertionError("simulated cuMemcpyHtoD should seed vector_add output")
