            os.environ[METAL_KERNELS_ENV] = "required"
            if launch_vector_add() != CUDA_SUCCESS:
                raise AssertionError("required Metal cuLaunchKernel path should run vector_add_f32 on Apple Silicon")
            assert_vector_add_output_matches("Metal vector_add_f32", a_host, b_host)
            a_host_repeat = (ctypes.c_float * vector_count)(*[float(i * 3 - 17) for i in range(vector_count)])
            b_host_repeat = (ctypes.c_float * vector_count)(*[float(7 - i * 2) for i in range(vector_count)])
            if libcuda.cuMemcpyHtoD(a_dev, ctypes.cast(a_host_repeat, ctypes.c_void_p), vector_bytes) != CUDA_SUCCESS:
                raise AssertionError("simulated cuMemcpyHtoD should refresh Metal vector_add input A")
            if libcuda.cuMemcpyHtoD(b_dev, ctypes.cast(b_host_repeat, ctypes.c_void_p), vector_bytes) != CUDA_SUCCESS:
                raise AssertionError("simulated cuMemcpyHtoD should refresh Metal vector_add input B")
