            overlap_count = vector_count + 1
            overlap_bytes = overlap_count * ctypes.sizeof(ctypes.c_float)
            overlap_dev = ctypes.c_ulonglong()
            overlap_seed = (ctypes.c_float * overlap_count)(*[float(200 - index * 0.5) for index in range(overlap_count)])
            overlap_out = (ctypes.c_float * overlap_count)()
