        a_arg.value = original_a
        assert_vector_add_output_zero("unregistered input A pointer launch")
        original_b = b_arg.value
        b_arg.value = 1
        if launch_vector_add() != CUDA_ERROR_INVALID_VALUE:
            raise AssertionError("simulated cuLaunchKernel should reject unregistered input B pointers")
        b_arg.value = original_b
        assert_vector_add_output_zero("unregistered input B pointer launch")
        reset_vector_add_output()
