    if current.value != -1:
        raise AssertionError("cudaGetDevice should set current device to -1")
    if libcudart.cudaSetDevice(0) != CUDA_ERROR_NO_DEVICE:
        raise AssertionError("cudaSetDevice should not accept device 0")
    if libcudart.cudaSetDevice(CUDA_CPU_DEVICE_ID) != CUDA_ERROR_NO_DEVICE:
        raise AssertionError("cudaSetDevice should not accept cudaCpuDeviceId as a CUDA device")
