    if libcudart.cudaGetDeviceProperties(buffer_ptr(fake_props), CUDA_CPU_DEVICE_ID) != CUDA_ERROR_NO_DEVICE:
        raise AssertionError("cudaGetDeviceProperties should not fabricate CPU pseudo-device properties")

