    total = ctypes.c_size_t(456)
    if libcudart.cudaMemGetInfo(ctypes.byref(free), ctypes.byref(total)) != CUDA_SUCCESS:
        raise AssertionError("cudaMemGetInfo should report empty memory accounting successfully")
    if free.value != 0 or total.value != 0:
        raise AssertionError(f"cudaMemGetInfo should report zero bytes, got {free.value}/{total.value}")

