    def make_layout(data_type: int, rows: int, cols: int, ld: int) -> ctypes.c_void_p:
        layout = ctypes.c_void_p()
        status = libcublaslt.cublasLtMatrixLayoutCreate(
            ctypes.byref(layout), data_type, rows, cols, ld
        )
        if status != CUBLAS_STATUS_SUCCESS:
            raise AssertionError(f"cublasLtMatrixLayoutCreate failed with {status}")
        return layout

    def make_desc(compute_type: int, scale_type: int) -> ctypes.c_void_p:
        desc = ctypes.c_void_p()
        status = libcublaslt.cublasLtMatmulDescCreate(
            ctypes.byref(desc), compute_type, scale_type
        )
        if status != CUBLAS_STATUS_SUCCESS:
            raise AssertionError(f"cublasLtMatmulDescCreate failed with {status}")
        return desc

    def make_transform_desc(scale_type: int) -> ctypes.c_void_p:
        desc = ctypes.c_void_p()
        status = libcublaslt.cublasLtMatrixTransformDescCreate(
            ctypes.byref(desc), scale_type
        )
        if status != CUBLAS_STATUS_SUCCESS:
            raise AssertionError(f"cublasLtMatrixTransformDescCreate failed with {status}")
        return desc

    def make_pref() -> ctypes.c_void_p:
        pref = ctypes.c_void_p()
        status = libcublaslt.cublasLtMatmulPreferenceCreate(ctypes.byref(pref))
        if status != CUBLAS_STATUS_SUCCESS:
            raise AssertionError(f"cublasLtMatmulPreferenceCreate failed with {status}")
        return pref

    def set_i32(fn, handle: ctypes.c_void_p, attr: int, value: int) -> None:
        raw = ctypes.c_int(value)
        status = fn(handle, attr, ctypes.byref(raw), ctypes.sizeof(raw))
        if status != CUBLAS_STATUS_SUCCESS:
            raise AssertionError(f"set attr {attr} failed with {status}")

    def set_u32(fn, handle: ctypes.c_void_p, attr: int, value: int) -> None:
        raw = ctypes.c_uint(value)
        status = fn(handle, attr, ctypes.byref(raw), ctypes.sizeof(raw))
        if status != CUBLAS_STATUS_SUCCESS:
            raise AssertionError(f"set attr {attr} failed with {status}")

