    def set_ptr(fn, handle: ctypes.c_void_p, attr: int, value: int | None) -> None:
        raw = ctypes.c_void_p(value)
        status = fn(handle, attr, ctypes.byref(raw), ctypes.sizeof(raw))
        if status != CUBLAS_STATUS_SUCCESS:
            raise AssertionError(f"set attr {attr} failed with {status}")

    def get_i32(fn, handle: ctypes.c_void_p, attr: int) -> int:
        raw = ctypes.c_int()
        written = ctypes.c_size_t()
        status = fn(handle, attr, ctypes.byref(raw), ctypes.sizeof(raw), ctypes.byref(written))
        if status != CUBLAS_STATUS_SUCCESS or written.value != ctypes.sizeof(raw):
            raise AssertionError(f"get attr {attr} failed with {status}/{written.value}")
        return raw.value

    def get_u32(fn, handle: ctypes.c_void_p, attr: int) -> int:
        raw = ctypes.c_uint()
        written = ctypes.c_size_t()
        status = fn(handle, attr, ctypes.byref(raw), ctypes.sizeof(raw), ctypes.byref(written))
        if status != CUBLAS_STATUS_SUCCESS or written.value != ctypes.sizeof(raw):
            raise AssertionError(f"get attr {attr} failed with {status}/{written.value}")
        return raw.value

    def get_i64(fn, handle: ctypes.c_void_p, attr: int) -> int:
        raw = ctypes.c_int64()
