        relu_aux_raw = [float(relu_aux_c[index]) for index in range(6)]
        assert_real_values_near(
            real_matrix_values(relu_aux_d, rows=2, cols=3, ld=2),
            [value if relu_active(value) else 0.0 for value in relu_aux_raw],
            "cublasLt FP32 ReLU_AUX D output",
        )
        if relu_aux_live_bits(relu_aux_mask, rows=2, cols=3, aux_ld=128) != [1 if relu_active(value) else 0 for value in relu_aux_raw]:
            raise AssertionError("cuBLASLt ReLU_AUX should write LSB-first live mask bits matching the ReLU clamp predicate")
        # With AUX_LD=128 bits, the three live columns start at bytes 0, 16, and 32.
        # Each 2-row column uses bit0 for row0 and bit1 for row1, so 0xA5 changes to:
        # col0: row0 inactive clears bit0, row1 active sets bit1 => 0xA6
        # col1: row0 inactive clears bit0, row1 inactive clears bit1 => 0xA4
        # col2: row0 active and row1 inactive preserve the initial bit0/bit1 state => 0xA5
        expected_relu_aux_bytes = {0: 0xA6, 16: 0xA4, 32: 0xA5}
        for byte_index, expected_byte in expected_relu_aux_bytes.items():
            if int(relu_aux_mask[byte_index]) != expected_byte:
                raise AssertionError("cuBLASLt ReLU_AUX should write the expected LSB-first mask bytes")
            if int(relu_aux_mask[byte_index]) & ~0x03 != 0xA5 & ~0x03:
                raise AssertionError("cuBLASLt ReLU_AUX should preserve non-live bits in each live mask byte")
        for byte_index in range(48):
            if byte_index not in {0, 16, 32} and int(relu_aux_mask[byte_index]) != 0xA5:
                raise AssertionError("cuBLASLt ReLU_AUX should leave mask padding bytes untouched")

