    if libnvml.nvmlDeviceGetHandleByPciBusId_v2(b"0000:00:00.0", ctypes.byref(handle)) != NVML_ERROR_NOT_FOUND:
        raise AssertionError("nvmlDeviceGetHandleByPciBusId_v2 should report no matching NVIDIA PCI device")

    fake_device = ctypes.c_void_p(0xABCDEF)
    name = ctypes.create_string_buffer(64)
    uuid = ctypes.create_string_buffer(80)
    memory = NvmlMemory()
    utilization = NvmlUtilization()
