    if libcudnn.cudnnSetActivationDescriptor(act_desc, CUDNN_ACTIVATION_SIGMOID, CUDNN_PROPAGATE_NAN, 0.0) != CUDNN_STATUS_SUCCESS:
        raise AssertionError("cuDNN shim should accept sigmoid before activation backward")
    sigmoid_dx_values = (ctypes.c_float * 8)(*activation_prior)
