    dx_nan_back[0] = 0.0
    status = libcudnn.cudnnActivationBackward(handle, act_desc, ctypes.byref(alpha), one_desc, y_nan_back, one_desc, dy_nan_back, one_desc, x_nan_back, ctypes.byref(beta), one_desc, dx_nan_back)
    if status != CUDNN_STATUS_SUCCESS:
        raise AssertionError("NOT_PROPAGATE_NAN tanh backward should run")
    assert_close_or_nan(dx_nan_back[0], 4.0, "NOT_PROPAGATE_NAN tanh NaN-x backward")

    if libcudnn.cudnnSetActivationDescriptor(act_desc, CUDNN_ACTIVATION_RELU, CUDNN_PROPAGATE_NAN, 0.0) != CUDNN_STATUS_SUCCESS:
        raise AssertionError("cuDNN shim should restore ReLU before backward alias tests")
    alias_x = [-1.0, 0.0, 2.0, 3.0]
    alias_y = (ctypes.c_float * 4)(9.0, 8.0, 7.0, 6.0)
    alias_dy_prior = [1.0, 2.0, 3.0, 4.0]
    alias_x_values = (ctypes.c_float * 4)(*alias_x)
    alias_dy_dx = (ctypes.c_float * 4)(*alias_dy_prior)
    alpha.value = 1.0
    beta.value = 0.5
    status = libcudnn.cudnnActivationBackward(
        handle,
        act_desc,
        ctypes.byref(alpha),
        four_desc,
        alias_y,
        four_desc,
        alias_dy_dx,
        four_desc,
        alias_x_values,
        ctypes.byref(beta),
        four_desc,
        alias_dy_dx,
    )
    if status != CUDNN_STATUS_SUCCESS:
        raise AssertionError("cudnnActivationBackward should allow exact dy == dx with identical descriptors")
    expected_alias_backward = expected_activation_backward(
        alias_x,
        alias_dy_prior,
        alias_dy_prior,
        CUDNN_ACTIVATION_RELU,
        CUDNN_PROPAGATE_NAN,
        1.0,
        0.5,
    )
    for index, (value, expected_value) in enumerate(zip(alias_dy_dx, expected_alias_backward)):
        assert_close_or_nan(value, expected_value, f"activation backward dy/dx alias[{index}]")

    activation_overlap = (ctypes.c_float * 9)(*range(9))
    if libcudnn.cudnnActivationBackward(handle, act_desc, ctypes.byref(alpha), y_desc, activation_y_values, y_desc, activation_overlap, x_desc, activation_x_values, ctypes.byref(beta), y_desc, ctypes.byref(activation_overlap, ctypes.sizeof(ctypes.c_float))) != CUDNN_STATUS_BAD_PARAM:
        raise AssertionError("cudnnActivationBackward should reject partial dy/dx overlaps")
    if list(activation_overlap) != [float(i) for i in range(9)]:
        raise AssertionError("activation backward partial dy/dx overlap rejection should leave storage unchanged")
    x_alias_dx = (ctypes.c_float * 8)(*finite_activation_x)
    x_alias_dy = (ctypes.c_float * 8)(*finite_activation_dy)
    x_alias_y = (ctypes.c_float * 8)(*activation_y)
    if libcudnn.cudnnActivationBackward(handle, act_desc, ctypes.byref(alpha), y_desc, x_alias_y, y_desc, x_alias_dy, x_desc, x_alias_dx, ctypes.byref(beta), x_desc, x_alias_dx) != CUDNN_STATUS_BAD_PARAM:
        raise AssertionError("cudnnActivationBackward should reject x/dx aliasing")
    y_alias_dx = (ctypes.c_float * 8)(*activation_y)
    if libcudnn.cudnnActivationBackward(handle, act_desc, ctypes.byref(alpha), y_desc, y_alias_dx, y_desc, x_alias_dy, x_desc, x_alias_dx, ctypes.byref(beta), y_desc, y_alias_dx) != CUDNN_STATUS_BAD_PARAM:
        raise AssertionError("cudnnActivationBackward should reject y/dx aliasing")
    if libcudnn.cudnnActivationBackward(handle, act_desc, ctypes.byref(alpha), bad_desc, activation_y_values, y_desc, activation_dy_values, x_desc, activation_x_values, ctypes.byref(beta), y_desc, activation_dx_values) != CUDNN_STATUS_BAD_PARAM:
        raise AssertionError("cudnnActivationBackward should reject mismatched y/x dimensions")

    os.environ[CUDNN_METAL_ENV] = "required"
    os.environ.pop(METAL_DISABLE_ENV, None)
    if libcudnn.cudnnSetActivationDescriptor(act_desc, CUDNN_ACTIVATION_TANH, CUDNN_PROPAGATE_NAN, 0.0) != CUDNN_STATUS_SUCCESS:
        raise AssertionError("cuDNN shim should accept tanh before required Metal activation backward")
    metal_activation_dx = (ctypes.c_float * 4)(0.0, 0.0, 0.0, 0.0)
    metal_activation_x = (ctypes.c_float * 4)(-1.0, 0.0, 1.0, 2.0)
    metal_activation_y = (ctypes.c_float * 4)(100.0, 100.0, 100.0, 100.0)
    metal_activation_dy = (ctypes.c_float * 4)(1.0, -2.0, 3.0, -4.0)
    alpha.value = 1.0
    beta.value = 0.0
    status = libcudnn.cudnnActivationBackward(
        handle,
        act_desc,
        ctypes.byref(alpha),
        four_desc,
        metal_activation_y,
        four_desc,
        metal_activation_dy,
        four_desc,
        metal_activation_x,
        ctypes.byref(beta),
        four_desc,
        metal_activation_dx,
    )
    if status != CUDNN_STATUS_SUCCESS:
        raise AssertionError("required cuDNN Metal mode should run activation backward")
    expected_metal_activation = expected_activation_backward(
        [-1.0, 0.0, 1.0, 2.0],
        [1.0, -2.0, 3.0, -4.0],
        [0.0, 0.0, 0.0, 0.0],
        CUDNN_ACTIVATION_TANH,
        CUDNN_PROPAGATE_NAN,
        1.0,
        0.0,
    )
    for index, (value, expected_value) in enumerate(zip(metal_activation_dx, expected_metal_activation)):
        assert_close_or_nan(value, expected_value, f"required Metal tanh activation backward[{index}]")

    os.environ[CUDNN_METAL_ENV] = "required"
    os.environ[METAL_DISABLE_ENV] = "1"
    disabled_activation_dx = (ctypes.c_float * 4)(7.0, 8.0, 9.0, 10.0)
    status = libcudnn.cudnnActivationBackward(
        handle,
        act_desc,
        ctypes.byref(alpha),
        four_desc,
        metal_activation_y,
        four_desc,
        metal_activation_dy,
        four_desc,
        metal_activation_x,
        ctypes.byref(beta),
        four_desc,
        disabled_activation_dx,
    )
    if status != CUDNN_STATUS_NOT_SUPPORTED:
        raise AssertionError("required cuDNN Metal activation backward should fail when the Metal backend is disabled")
    if list(disabled_activation_dx) != [7.0, 8.0, 9.0, 10.0]:
        raise AssertionError("required Metal activation backward failure should leave dx unchanged")

    os.environ[CUDNN_METAL_ENV] = "1"
    os.environ[METAL_DISABLE_ENV] = "1"
    fallback_activation_dx = (ctypes.c_float * 4)(0.0, 0.0, 0.0, 0.0)
    status = libcudnn.cudnnActivationBackward(
        handle,
        act_desc,
        ctypes.byref(alpha),
        four_desc,
        metal_activation_y,
        four_desc,
        metal_activation_dy,
        four_desc,
        metal_activation_x,
        ctypes.byref(beta),
        four_desc,
        fallback_activation_dx,
    )
    if status != CUDNN_STATUS_SUCCESS:
        raise AssertionError("preferred cuDNN Metal activation backward should fall back to CPU when backend is unavailable")
    for index, (value, expected_value) in enumerate(zip(fallback_activation_dx, expected_metal_activation)):
        assert_close_or_nan(value, expected_value, f"preferred fallback activation backward[{index}]")
    os.environ.pop(METAL_DISABLE_ENV, None)
    os.environ.pop(CUDNN_METAL_ENV, None)

    def expected_batchnorm_inference(
        x_values: list[float],
        y_prior: list[float],
        dims: tuple[int, int, int, int],
        scale: list[float],
        bias: list[float],
        mean: list[float],
        variance: list[float],
        mode: int,
        alpha_value: float,
        beta_value: float,
        epsilon: float,
    ) -> list[float]:
        result: list[float] = []
        n_dim, c_dim, h_dim, w_dim = dims
        for batch in range(n_dim):
            for channel in range(c_dim):
                for row in range(h_dim):
                    for column in range(w_dim):
                        index = ((batch * c_dim + channel) * h_dim + row) * w_dim + column
                        if mode == CUDNN_BATCHNORM_PER_ACTIVATION:
                            param_index = (channel * h_dim + row) * w_dim + column
                        else:
                            param_index = channel
                        normalized = bias[param_index] + scale[param_index] * (x_values[index] - mean[param_index]) / math.sqrt(epsilon + variance[param_index])
                        prior = y_prior[index] if beta_value != 0.0 else 0.0
                        result.append(alpha_value * normalized + beta_value * prior)
        return result

    bn_alpha = ctypes.c_float(1.0)
    bn_beta = ctypes.c_float(0.0)
    bn_epsilon = CUDNN_BN_MIN_EPSILON
    bn_x = [float(index - 8) / 3.0 for index in range(24)]
    bn_spatial_prior = [float(index + 1) for index in range(24)]
    bn_scale = [1.0, -0.5, 2.0]
    bn_bias = [0.25, -1.0, 1.5]
    bn_mean = [0.5, -0.25, 2.0]
    bn_variance = [1.0, 4.0, 0.25]
    bn_x_values = (ctypes.c_float * 24)(*bn_x)
    bn_y_values = (ctypes.c_float * 24)(*bn_spatial_prior)
    bn_scale_values = (ctypes.c_float * 3)(*bn_scale)
    bn_bias_values = (ctypes.c_float * 3)(*bn_bias)
    bn_mean_values = (ctypes.c_float * 3)(*bn_mean)
    bn_variance_values = (ctypes.c_float * 3)(*bn_variance)
    status = libcudnn.cudnnBatchNormalizationForwardInference(
        handle,
        CUDNN_BATCHNORM_SPATIAL,
        ctypes.byref(bn_alpha),
        ctypes.byref(bn_beta),
        add_c_desc,
        bn_x_values,
        add_c_desc,
        bn_y_values,
        bn_spatial_desc,
        bn_scale_values,
        bn_bias_values,
        bn_mean_values,
        bn_variance_values,
        bn_epsilon,
    )
    if status != CUDNN_STATUS_SUCCESS:
        raise AssertionError("cudnnBatchNormalizationForwardInference should run spatial FP32 NCHW")
    for index, (value, expected_value) in enumerate(zip(bn_y_values, expected_batchnorm_inference(bn_x, bn_spatial_prior, (2, 3, 2, 2), bn_scale, bn_bias, bn_mean, bn_variance, CUDNN_BATCHNORM_SPATIAL, bn_alpha.value, bn_beta.value, bn_epsilon))):
        assert_close_or_nan(value, expected_value, f"spatial BatchNormInference[{index}]")

    bn_per_scale = [1.0 + 0.1 * index for index in range(12)]
    bn_per_bias = [-0.5 + 0.05 * index for index in range(12)]
    bn_per_mean = [0.25 - 0.02 * index for index in range(12)]
    bn_per_variance = [0.5 + 0.25 * index for index in range(12)]
    bn_per_prior = [float(index % 5) for index in range(24)]
    bn_per_y = (ctypes.c_float * 24)(*bn_per_prior)
    bn_alpha.value = 1.5
    bn_beta.value = 0.25
    status = libcudnn.cudnnBatchNormalizationForwardInference(
        handle,
        CUDNN_BATCHNORM_PER_ACTIVATION,
        ctypes.byref(bn_alpha),
        ctypes.byref(bn_beta),
        add_c_desc,
        bn_x_values,
        add_c_desc,
        bn_per_y,
        bn_per_activation_desc,
        (ctypes.c_float * 12)(*bn_per_scale),
        (ctypes.c_float * 12)(*bn_per_bias),
        (ctypes.c_float * 12)(*bn_per_mean),
        (ctypes.c_float * 12)(*bn_per_variance),
        bn_epsilon,
    )
    if status != CUDNN_STATUS_SUCCESS:
        raise AssertionError("cudnnBatchNormalizationForwardInference should run per-activation FP32 NCHW")
    for index, (value, expected_value) in enumerate(zip(bn_per_y, expected_batchnorm_inference(bn_x, bn_per_prior, (2, 3, 2, 2), bn_per_scale, bn_per_bias, bn_per_mean, bn_per_variance, CUDNN_BATCHNORM_PER_ACTIVATION, bn_alpha.value, bn_beta.value, bn_epsilon))):
        assert_close_or_nan(value, expected_value, f"per-activation BatchNormInference[{index}]")

    bn_poison_prior = [float("nan")] * 24
    bn_poison_y = (ctypes.c_float * 24)(*bn_poison_prior)
    bn_alpha.value = 2.0
    bn_beta.value = -0.0
    status = libcudnn.cudnnBatchNormalizationForwardInference(
        handle,
        CUDNN_BATCHNORM_SPATIAL,
        ctypes.byref(bn_alpha),
        ctypes.byref(bn_beta),
        add_c_desc,
        bn_x_values,
        add_c_desc,
        bn_poison_y,
        bn_spatial_desc,
        bn_scale_values,
        bn_bias_values,
        bn_mean_values,
        bn_variance_values,
        bn_epsilon,
    )
    if status != CUDNN_STATUS_SUCCESS:
        raise AssertionError("cudnnBatchNormalizationForwardInference should run with beta == -0.0")
