    if status != CUDNN_STATUS_SUCCESS:
        raise AssertionError("cudnnAddTensor should run with beta == 0")
    for index, (value, expected_value) in enumerate(zip(add_beta_zero_c, expected_add_tensor(add_bias, (1, 3, 1, 1), add_beta_zero_prior, (2, 3, 2, 2), add_alpha.value, add_beta.value))):
        assert_close_or_nan(value, expected_value, f"beta-zero AddTensor[{index}]")

    add_alpha_zero_a = (ctypes.c_float * 4)(float("nan"), 2.0, -3.0, 4.0)
    add_alpha_zero_prior = [1.0, 2.0, 3.0, 4.0]
    add_alpha_zero_c = (ctypes.c_float * 4)(*add_alpha_zero_prior)
    add_alpha.value = 0.0
    add_beta.value = 1.0
    status = libcudnn.cudnnAddTensor(
        handle,
        ctypes.byref(add_alpha),
        four_desc,
        add_alpha_zero_a,
        ctypes.byref(add_beta),
        four_desc,
        add_alpha_zero_c,
    )
    if status != CUDNN_STATUS_SUCCESS:
        raise AssertionError("cudnnAddTensor should run with alpha == 0")
    for index, (value, expected_value) in enumerate(zip(add_alpha_zero_c, [math.nan, 2.0, 3.0, 4.0])):
        assert_close_or_nan(value, expected_value, f"alpha-zero AddTensor[{index}]")

    if libcudnn.cudnnAddTensor(handle, ctypes.byref(add_alpha), add_bad_desc, add_bias_values, ctypes.byref(add_beta), add_c_desc, add_bias_c) != CUDNN_STATUS_BAD_PARAM:
        raise AssertionError("cudnnAddTensor should reject broadcast-incompatible dimensions")

    add_inplace = (ctypes.c_float * 4)(1.0, 2.0, 3.0, 4.0)
    add_alpha.value = 1.0
    add_beta.value = 0.5
    if libcudnn.cudnnAddTensor(handle, ctypes.byref(add_alpha), four_desc, add_inplace, ctypes.byref(add_beta), four_desc, add_inplace) != CUDNN_STATUS_BAD_PARAM:
        raise AssertionError("cudnnAddTensor should reject exact A == C overlap in v1")
    if list(add_inplace) != [1.0, 2.0, 3.0, 4.0]:
        raise AssertionError("rejected AddTensor in-place call should leave storage unchanged")

    add_overlap = (ctypes.c_float * 8)(*range(8))
    if libcudnn.cudnnAddTensor(handle, ctypes.byref(add_alpha), four_desc, add_overlap, ctypes.byref(add_beta), four_desc, ctypes.byref(add_overlap, ctypes.sizeof(ctypes.c_float))) != CUDNN_STATUS_BAD_PARAM:
        raise AssertionError("cudnnAddTensor should reject partial A/C overlap")
    if list(add_overlap) != [float(index) for index in range(8)]:
        raise AssertionError("rejected AddTensor partial-overlap call should leave storage unchanged")

    add_adjacent = (ctypes.c_float * 8)(1.0, 2.0, 3.0, 4.0, 10.0, 20.0, 30.0, 40.0)
