    for value, expected_value in zip(avg_y_beta, [12.0, 19.0, 26.0, 35.0, 42.0, 49.0]):
        if not math.isclose(value, expected_value, rel_tol=1e-6, abs_tol=1e-6):
            raise AssertionError("average pooling alpha/beta result mismatch")
    pool_alpha.value = 1.0
    pool_beta.value = 0.0
    if libcudnn.cudnnPoolingForward(handle, pool_desc, ctypes.byref(pool_alpha), pool_x_desc, pool_x, ctypes.byref(pool_beta), bad_desc, pool_y) != CUDNN_STATUS_BAD_PARAM:
        raise AssertionError("cudnnPoolingForward should reject y descriptors that do not match computed output dims")
    pool_overlap = (ctypes.c_float * 13)(*range(13))
